contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val, address logAddr) public payable {
        require(true);

        bool preReverted;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { preReverted = true; } else { preReverted = false; }

        bool initReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { initReverted = true; } else { initReverted = false; }

        uint minSumAfterInit = c.MinSum(); if (__ESBMC_reverted()) return;

        bool postReverted;
        c.SetMinSum(val); bool __rev2 = __ESBMC_reverted(); if (__rev2) { postReverted = true; } else { postReverted = false; }

        bool logReverted;
        c.SetLogFile(logAddr); bool __rev3 = __ESBMC_reverted(); if (__rev3) { logReverted = true; } else { logReverted = false; }

        assert(!preReverted && !initReverted && postReverted && logReverted && minSumAfterInit == val);
    }

    receive() external payable {}
}

